-- L14121
         --[E20260930-DMF0082FXZERO] 원문: , ROUND(NVL(T.QTY_PRICE, 0) * CASE WHEN T.CURRENCY = 'KRW' THEN 1 ELSE EX.EXCHANGE_PRICE END, 3) AS QTY_PRICE --[E20260309-000271]_ISNULL처리 추가
         , ROUND(NVL(T.QTY_PRICE, 0) * CASE WHEN T.CURRENCY = 'KRW' THEN 1 ELSE NVL(EX.EXCHANGE_PRICE, 0) END, 3) AS QTY_PRICE   -- 환율 없으면 KRW 0
-- L14135
         --[E20260930-DMF0082FXZERO] 원문: , ROUND(ROUND((NVL(T.QTY_PRICE, 0) * CASE WHEN T.CURRENCY = 'KRW' THEN 1 ELSE EX.EXCHANGE_PRICE END), 3) / USD.EXCHANGE_PRICE, 3) AS QTY_PRICE --[E20260309-000271]_ISNULL처리 추가
         , CASE WHEN NVL(USD.EXCHANGE_PRICE, 0) = 0 THEN CASE WHEN T.CURRENCY = 'USD' THEN NVL(T.QTY_PRICE, 0) ELSE 0 END   -- USD 환율 없으면 0 (통화 USD 면 LOC 그대로)
                ELSE ROUND(ROUND((NVL(T.QTY_PRICE, 0) * CASE WHEN T.CURRENCY = 'KRW' THEN 1 ELSE NVL(EX.EXCHANGE_PRICE, 0) END), 3) / USD.EXCHANGE_PRICE, 3) END AS QTY_PRICE
